        },
        {
            "code": "FACILITYWITHBOUNDARY_README_HEADER_1_DESC_2",
            "message": "Téléchargez le modèle Excel en cliquant sur le bouton « Télécharger le modèle ».",
            "module": "rainmaker-hcm-admin-schemas",
